        runCompare: true,
        compareMode: "template",
        comparePayload: { template: tmpl },
      };
      if (typeof runDeal360Analysis === "function") runDeal360Analysis();
    } else if (mode === "upload") {
      var fileInp = document.getElementById("cmpFileInput");
