          (idx + 1) +
          "</div>" +
          '<strong id="compare-title-' +
          idx +
          '" style="font-size:14px; color:#1e293b; letter-spacing:-0.2px; display:flex; align-items:center;">Section ' +
          (item.section || "") +
          ' <span style="margin-left:8px; font-size:8px; font-weight:800; background:' +
          zone.snippetBg +
