          "</div>" +
          '<div style="display:flex; flex-direction:column; gap:8px;">' +
          snippetsHtml +
          "</div>" +
          // Action row — apply button is independent of the impact panel
          // so it shows on every diff card (even those without legal_impact).
          (applyBtnHtml
            ? '<div style="margin-top:10px; display:flex; justify-content:flex-end;">' + applyBtnHtml + '</div>'
            : "") +
          (item.legal_impact
            ? '<div style="margin-top:10px; padding:10px 12px; background:#f5f9ff; border-left:3px solid #1565c0; font-size:11px; color:#37474f; line-height:1.5; box-shadow:inset 0 1px 3px rgba(0,0,0,0.02);"><div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; border-bottom:1px solid rgba(21,101,192,0.1); padding-bottom:6px;"><span style="font-weight:900; color:#1565c0; font-size:10px; text-transform:uppercase; letter-spacing:1px;">IMPACT ANALYSIS</span>' +
            deepDiveHtml +
