            item.legal_impact +
            "</div>"
            : "");
        card.innerHTML = html;
        if (canLocate) {
          card.style.cursor = "pointer";
          card.title = "Click to locate this change";
          card.onclick = function () {
            compareLocateFromCard(
              anchorId || locatorSearchStr,
              safeSect,
              card,
              isDeletion,
              safeDeletedSnippet,
              safeOriginalSnippet,
              safeNewSnippet
            );
          };
          var innerBtns = card.querySelectorAll("button");
          innerBtns.forEach(function (b) {
            b.addEventListener("click", function (e) {
              e.stopPropagation();
            });
          });
