        masterBody.appendChild(card);
      });
    });
    targetContainer.appendChild(masterWrapper);
  }
  var btnHome = document.createElement("button");
  btnHome.innerHTML = '<span style="margin-right:6px;">\u2190</span> Home';
  btnHome.style.cssText =
    "width:100%; margin-top:16px; padding:13px 16px; font-size:11px; font-weight:800; letter-spacing:0.5px; text-transform:uppercase; cursor:pointer; " +
    "background:linear-gradient(135deg,#0f172a,#1e293b); color:#94a3b8; border:1.5px solid #334155; border-radius:0; " +
    "font-family:'Segoe UI',system-ui,sans-serif; transition:all 0.15s; box-shadow:0 2px 8px rgba(15,23,42,0.2);";
  btnHome.onmouseover = function () {
