}

functions._compareParseJson:
function _compareParseJson(jsonString) {
  if (!jsonString) return {};
  var clean = String(jsonString)
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .replace(/^[^{[]*/, "")
    .replace(/[^}\]]*$/, "")
    .trim();
  try { return JSON.parse(clean); }
  catch (e) {
    try {
      var recovered = [];
      var rx = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g, m;
      while ((m = rx.exec(clean)) !== null) {
        try { recovered.push(JSON.parse(m[0])); } catch (e2) { /* skip */ }
      }
      if (recovered.length > 0) return recovered;
    } catch (e3) { /* fall through */ }
    try {
      var fixed = clean.replace(/(?<!["}])\n/g, "\\n");
      if (fixed.match(/^\[\w+\]/)) throw new Error("plain text list");
      return JSON.parse(fixed);
    } catch (e4) {
      if (jsonString.indexOf("1.") !== -1 || jsonString.indexOf("- ") !== -1) {
        return {
          summary: "AI returned plain text analysis.",
          changes: [{ clause: "General", change: String(jsonString).substring(0, 500), impact: "Review Manually" }],
        };
      }
      if (clean.charAt(0) === "[") return [];
      return {};
    }
  }
}

functions.runVersionCompare:
function runVersionCompare(historicalVersion) {
  setLoading(!0, "redline");
  Word.run(async (context) => {
    let body = context.document.body;
    let html = body.getHtml();
    let ooxml = body.getOoxml();
    await context.sync();
    return { html: html.value, ooxml: ooxml.value };
  })
    .then((current) => {
      let currentHtml = current.html || "";
      let currentOoxml = current.ooxml || "";
      let currentText = getCleanTextAndContext(currentHtml).text;
      let oldText = getCleanTextAndContext(historicalVersion.html || "").text;
      let histLabel = historicalVersion.displayNumber
        ? "Version #" + historicalVersion.displayNumber
        : "Historical Snapshot";
      let currentLabel = "Current Active Document";
      // Strip noise from current OOXML so the diff isn't drowned in rsids/dates.
      if (currentOoxml && typeof _tpStripOoxmlNoise === "function") {
        currentOoxml = _tpStripOoxmlNoise(currentOoxml);
      }
      // Redline-aware diff via OOXML — captures accept/reject decisions that pure
      // text comparison can't see. Falls back gracefully when either snapshot
      // pre-dates the bodyOoxml capture (older snapshots have only `html`).
      let transitionsBlock = "";
      let rawCompareResult = null; // raw output from compareSnapshotsRedlineAware,
                                   // surfaced via the "🔍 Raw transitions" debug
                                   // button in the Executive Summary card.
      if (
        historicalVersion.bodyOoxml &&
        currentOoxml &&
        typeof window.compareSnapshotsRedlineAware === "function"
      ) {
        try {
          let result = window.compareSnapshotsRedlineAware(
            { bodyOoxml: historicalVersion.bodyOoxml },
            { bodyOoxml: currentOoxml },
          );
          rawCompareResult = result;
          if (result && Array.isArray(result.transitions)) {
            let typeLabel = {
              "accepted-insertion": "ACCEPTED INSERTION",
              "rejected-insertion": "REJECTED INSERTION",
              "accepted-deletion": "ACCEPTED DELETION",
              "rejected-deletion": "REJECTED DELETION",
              "new-insertion": "NEW PENDING INSERTION (introduced after snapshot)",
              "new-deletion": "NEW PENDING DELETION (introduced after snapshot)",
              "unmarked-change": "⚠️ UNMARKED CHANGE (edit made WITHOUT track changes — possible attempt to hide a redline)",
            };
            // Filter to state-change transitions ONLY. retained-pending-* means
            // the same redline was pending in v1 and is still pending in v2 —
            // that's NOT a change between versions and must not be reported.
            let stateChanges = result.transitions.filter(function (t) {
              return typeLabel.hasOwnProperty(t.type);
            });
            let s = result.summary || {};
            if (stateChanges.length === 0) {
              // Use a "no changes" sentinel so the AI knows to report nothing.
              transitionsBlock =
                "REDLINE-STATE TRANSITIONS: NO STATE CHANGES BETWEEN VERSIONS.\n" +
                "Both versions contain the same set of pending redlines (" + (s.retained || 0) + " retained). " +
                "No insertions or deletions were accepted, rejected, or newly introduced between the two snapshots. " +
                "Report this as no changes.\n\n";
            } else {
              // Cap at 200 transitions so the prompt stays bounded.
              let evidence = stateChanges.slice(0, 200).map(function (t) {
                let txt = String(t.text || "").replace(/\s+/g, " ").trim();
                if (txt.length > 240) txt = txt.slice(0, 240) + "…";
                let by = t.author ? " · author: " + t.author : "";
                return "- [" + (typeLabel[t.type] || t.type) + "]" + by + " · ¶" + t.paragraphIdx + ": \"" + txt + "\"";
              }).join("\n");
              transitionsBlock =
                "REDLINE-STATE TRANSITIONS (extracted from each version's OOXML — these are AUTHORITATIVE):\n" +
                "Accepted: " + (s.accepted || 0) +
                " | Rejected: " + (s.rejected || 0) +
                " | New counterparty redlines: " + (s.newRedlines || 0) +
                " | ⚠️ UNMARKED CHANGES (no track-changes wrapper — possible hidden redlines): " + (s.unmarked || 0) +
                " | Still pending (NOT a change — informational only): " + (s.retained || 0) + "\n\n" +
                evidence + "\n\n" +
                "IMPORTANT: still-pending redlines are NOT included above and are NOT changes between the two versions. Only the rows above are real changes. Report ONLY those rows — do not invent additional findings from the cleaned-text comparison.\n\n" +
                ((s.unmarked || 0) > 0
                  ? "⚠️ CRITICAL: " + s.unmarked + " UNMARKED CHANGE(S) detected. These are text edits the counterparty made without enabling Track Changes — they appear as identical differences in BOTH the accepted-view and rejected-view of the document. Treat each unmarked change as HIGH RISK in your findings, label it clearly as 'Unmarked edit' or 'Possible hidden redline', and recommend the reviewer manually verify the substantive impact.\n\n"
                  : "");
            }
          }
        } catch (_e) { /* fall through to text-only diff */ }
      }
      let prompt = `
      You are a Senior Legal Editor.
      TASK: Compare two document versions and write an executive summary.
      1. NAME A: "${histLabel}"
      2. NAME B: "${currentLabel}"
      ${transitionsBlock
          ? "PRIMARY EVIDENCE — drive your summary from this. Each line tells you exactly which redline transitioned to which state between the two versions. Group related transitions into clause-level findings:\n\n" + transitionsBlock
          : ""}
      INPUT TEXT FOR "${histLabel}":
      """${oldText.substring(0, 500000)}"""
      INPUT TEXT FOR "${currentLabel}":
      """${currentText.substring(0, 500000)}"""
      CRITICAL ANALYSIS RULES:
      1. IGNORE MISSING NUMBERING: The text extraction process often strips automatic list numbers (e.g. "1.", "2.1"). **DO NOT** report "removed numbering" or "continuous block of text" as a change. Assume the numbering exists in the source.
      2. FOCUS ON MEANING: Only report changes to words, definitions, obligations, or financial terms.
      3. IGNORE WHITESPACE: Ignore extra newlines or spacing differences.
      4. ${transitionsBlock
          ? "Trust the TRANSITIONS BLOCK above as the authoritative source of what changed. The cleaned text is supplementary context. If transitions list 5 accepted insertions, your output MUST reflect those accept decisions — do NOT report 'no changes detected' just because cleaned-text comparison looks similar."
          : "Compare the cleaned text of both versions for substantive changes."}
      OUTPUT FORMAT (STRICT JSON ONLY):
      {
        "summary": "Start with: Comparing ${histLabel} vs ${currentLabel}...",
        "changes": [
           { "clause": "Clause Name (e.g. Indemnity)", "change": "Description of change...", "impact": "High Risk" | "Neutral" | "Better" }
        ]
      }
    `;
      // Stash the raw compare result globally so the in-app "🔍 Raw transitions"
      // debug button (rendered in renderVersionReport) can show the JSON without
      // needing devtools. Cleared on each new compare run.
      window._eliLastCompareResult = rawCompareResult;
      return window.eli.ai.complete(prompt).then((result) => {
        let analysis = _compareParseJson(result);
        // Pass the transitions block + raw result through to renderVersionReport
        // so the Deep Dive button can leverage the same redline-aware evidence
        // and the debug button can display the raw JSON.
        renderVersionReport(analysis, historicalVersion.label, oldText, currentText, transitionsBlock, rawCompareResult);
      });
    })
    .catch(handleError)
    .finally(() => setLoading(!1));
}

functions.renderVersionReport:
function renderVersionReport(data, verLabel, oldText, currentText, transitionsBlock, rawCompareResult) {
  if (!data) data = {};
  if (!data.summary) data.summary = "Analysis unavailable.";
  if (!Array.isArray(data.changes)) data.changes = [];
  let out = window.eli.ui.claimOutput();
  let header = createConfigHeader(null, "🕒", "Version Report: " + verLabel, { marginBottom: "12px" });
  out.appendChild(header);
  // ⚠️ Unmarked-change warning card. Rendered ABOVE the executive summary so a
  // reviewer can't miss it — these are edits the counterparty made without
  // enabling Track Changes (possibly hiding redlines), detected by the dual-
  // diff in compareSnapshotsRedlineAware.
  let unmarkedChanges = rawCompareResult && Array.isArray(rawCompareResult.transitions)
    ? rawCompareResult.transitions.filter(function (t) { return t.type === "unmarked-change"; })
    : [];
  if (unmarkedChanges.length > 0) {
    let warn = document.createElement("div");
    warn.style.cssText = "border:2px solid #d97706; background:linear-gradient(135deg,#fef3c7,#fde68a); padding:14px 16px; margin-bottom:15px; border-left-width:6px;";
    let rowsHtml = unmarkedChanges.slice(0, 25).map(function (t) {
      let label = t.wholeParagraph ? "Whole paragraph added (no track changes)" : "Inline edit (no track changes)";
      let body = String(t.text || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      return '<tr style="border-bottom:1px solid #fcd34d;">' +
             '<td style="padding:7px 8px; font-weight:700; color:#92400e; vertical-align:top; white-space:nowrap;">¶' + (t.paragraphIdx + 1) + '</td>' +
             '<td style="padding:7px 8px; color:#78350f; vertical-align:top; font-weight:600;">' + label + '</td>' +
             '<td style="padding:7px 8px; color:#451a03; vertical-align:top; font-family:ui-monospace,Consolas,monospace; font-size:11px; line-height:1.45;">' + body + '</td>' +
             '</tr>';
    }).join("");
    let truncatedNote = unmarkedChanges.length > 25
      ? '<div style="margin-top:8px; font-size:11px; color:#92400e; font-style:italic;">…and ' + (unmarkedChanges.length - 25) + ' more — see "🔍 Raw transitions debug" for the complete list.</div>'
      : '';
    warn.innerHTML =
      '<div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">' +
        '<div style="font-size:20px;">⚠️</div>' +
        '<div style="font-size:13px; font-weight:800; color:#7c2d12; text-transform:uppercase; letter-spacing:0.5px;">' +
          unmarkedChanges.length + ' Unmarked Change' + (unmarkedChanges.length > 1 ? 's' : '') + ' Detected (Possible Hidden Redlines)' +
        '</div>' +
      '</div>' +
