functions.compareLocateFromCard:
function compareLocateFromCard(
  searchText,
  clauseRef,
  btnElement,
  isDeletion,
  encodedDeletedSnippet,
  encodedOriginalSnippet,
  encodedNewSnippet
) {
  if (searchText && String(searchText).indexOf("_ELI_") === 0) {
    if (typeof window.jumpToBookmark === "function") {
      window.jumpToBookmark(searchText);
    }
    return;
  }
  var deletedSnippet = "";
  var originalSnippet = "";
  var newSnippet = "";
  try {
    deletedSnippet = encodedDeletedSnippet ? decodeURIComponent(encodedDeletedSnippet) : "";
  } catch (e) {
    deletedSnippet = encodedDeletedSnippet || "";
  }
  try {
    originalSnippet = encodedOriginalSnippet ? decodeURIComponent(encodedOriginalSnippet) : "";
  } catch (e) {
    originalSnippet = encodedOriginalSnippet || "";
  }
  try {
    newSnippet = encodedNewSnippet ? decodeURIComponent(encodedNewSnippet) : "";
  } catch (e) {
    newSnippet = encodedNewSnippet || "";
  }
  locateCompareLikeTrackChanges(searchText, btnElement, clauseRef, clauseRef, {
    isDeletion: !!isDeletion,
    deletedSnippet: deletedSnippet,
    originalSnippet: originalSnippet,
    newSnippet: newSnippet,
    hasTrackedPriority: !!isDeletion || (originalSnippet && newSnippet),
  });
}

functions._tpDecodeXmlEntities:
function _tpDecodeXmlEntities(s) {
  return String(s)
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

// Extract per-paragraph redline spans. Returns:
//   [{ idx, paraId, acceptedText, originalText, pendingIns:[{text,author,date},...], pendingDel:[...] }, ...]

functions._eliExtractParagraphRedlineSpans:
function _eliExtractParagraphRedlineSpans(xml) {
  if (!xml) return [];
  // _tpStripOoxmlNoise is shimmed in compare/init.js. Tolerate its absence.
  var normalized = typeof window._tpStripOoxmlNoise === "function"
    ? window._tpStripOoxmlNoise(xml)
    : xml;
  var pRegex = /<w:p\b[^>]*\/>|<w:p\b[^>]*>[\s\S]*?<\/w:p>/g;
  var paragraphs = [];
  var pm;
  var pIdx = 0;
  var pullText = function (frag) {
    var rg = /<w:(?:t|delText)\b[^>]*>([\s\S]*?)<\/w:(?:t|delText)>/g;
    var parts = [];
    var m;
    while ((m = rg.exec(frag)) !== null) parts.push(_tpDecodeXmlEntities(m[1]));
    return parts.join("").replace(/\s+/g, " ").trim();
  };
  var attrs = function (tag) {
    var a = (tag.match(/w:author="([^"]*)"/) || [])[1] || "";
    var d = (tag.match(/w:date="([^"]*)"/) || [])[1] || "";
    return { author: a, date: d };
  };
  while ((pm = pRegex.exec(normalized)) !== null) {
    var rawPXml = pm[0];
    var paraId = "";
    var openTagMatch = rawPXml.match(/^<w:p\b[^>]*>/);
    if (openTagMatch) {
      var idMatch = openTagMatch[0].match(/w14:paraId="([^"]*)"/);
      if (idMatch) paraId = idMatch[1];
    }
    var pXml = rawPXml
      .replace(/<w:pPr>[\s\S]*?<\/w:pPr>/g, "")
      .replace(/<w:rPr>[\s\S]*?<\/w:rPr>/g, "");
    var pendingIns = [];
    var pendingDel = [];
    var insRe = /<w:ins\b([^>]*)>([\s\S]*?)<\/w:ins>/g;
    var im;
    while ((im = insRe.exec(pXml)) !== null) {
      var insTxt = pullText(im[2]);
      if (insTxt) pendingIns.push(Object.assign({ text: insTxt }, attrs("<w:ins" + im[1] + ">")));
    }
    var delRe = /<w:del\b([^>]*)>([\s\S]*?)<\/w:del>/g;
    var dm;
    while ((dm = delRe.exec(pXml)) !== null) {
      var delTxt = pullText(dm[2]);
      if (delTxt) pendingDel.push(Object.assign({ text: delTxt }, attrs("<w:del" + dm[1] + ">")));
    }
    var acceptedFrag = pXml.replace(/<w:del\b[^>]*>[\s\S]*?<\/w:del>/g, "");
    var acceptedText = pullText(acceptedFrag);
    var originalFrag = pXml.replace(/<w:ins\b[^>]*>[\s\S]*?<\/w:ins>/g, "");
    var originalText = pullText(originalFrag);
    paragraphs.push({
      idx: pIdx++,
      paraId: paraId,
      acceptedText: acceptedText,
      originalText: originalText,
      pendingIns: pendingIns,
      pendingDel: pendingDel,
    });
  }
  return paragraphs;
}

// Compare two snapshots' bodyOoxml. Returns:
//   { transitions: [...], summary: { accepted, rejected, newRedlines, retained, unmarked } }
// Each transition: { type, paragraphIdx, paraId, text, author, date, source }
// type ∈ accepted-insertion | rejected-insertion | accepted-deletion |
//        rejected-deletion | new-insertion | new-deletion |
//        retained-pending-insertion | retained-pending-deletion |
//        unmarked-change

functions.compareSnapshotsRedlineAware:
function compareSnapshotsRedlineAware(v1Snap, v2Snap) {
  var v1Xml = (v1Snap && v1Snap.bodyOoxml) || "";
  var v2Xml = (v2Snap && v2Snap.bodyOoxml) || "";
  if (!v1Xml || !v2Xml) {
    return {
      transitions: [],
      summary: { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 },
      error: !v1Xml && !v2Xml ? "Both snapshots are missing bodyOoxml" :
        (!v1Xml ? "v1 snapshot has no bodyOoxml" : "v2 snapshot has no bodyOoxml"),
    };
  }
  var v1Paras = _eliExtractParagraphRedlineSpans(v1Xml);
  var v2Paras = _eliExtractParagraphRedlineSpans(v2Xml);
  var transitions = [];
  var counts = { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 };
  var normText = function (s) { return String(s || "").replace(/\s+/g, " ").trim().toLowerCase(); };
  var redlineKey = function (entry) { return normText(entry.text) + " " + (entry.author || ""); };
  var collectRedlines = function (paras, source) {
    var ins = [], del = [];
    paras.forEach(function (p, idx) {
      p.pendingIns.forEach(function (e) {
        ins.push({ text: e.text, author: e.author, date: e.date, paraId: p.paraId, paraIdx: idx, source: source });
      });
      p.pendingDel.forEach(function (e) {
        del.push({ text: e.text, author: e.author, date: e.date, paraId: p.paraId, paraIdx: idx, source: source });
      });
    });
    return { ins: ins, del: del };
  };
  var v1R = collectRedlines(v1Paras, "v1");
  var v2R = collectRedlines(v2Paras, "v2");
  var buildSet = function (arr) {
    var map = {};
    arr.forEach(function (e) { var k = redlineKey(e); if (!map[k]) map[k] = e; });
    return map;
  };
  var v1InsSet = buildSet(v1R.ins);
  var v1DelSet = buildSet(v1R.del);
  var v2InsSet = buildSet(v2R.ins);
  var v2DelSet = buildSet(v2R.del);
  var v2CleanText = v2Paras.map(function (p) { return p.acceptedText || ""; }).join(" ");
  var v2CleanLower = normText(v2CleanText);
  var v1CleanLower = normText(v1Paras.map(function (p) { return p.acceptedText || ""; }).join(" "));
  var inV2Clean = function (text) {
    var n = normText(text);
    if (n.length < 4) return false;
    return v2CleanLower.indexOf(n) !== -1;
  };
  var inV1Clean = function (text) {
    var n = normText(text);
    if (n.length < 4) return false;
    return v1CleanLower.indexOf(n) !== -1;
  };
  // v1 insertions: retained-pending / accepted / rejected
  Object.keys(v1InsSet).forEach(function (k) {
    var ins = v1InsSet[k];
    if (v2InsSet[k]) {
      transitions.push({
        type: "retained-pending-insertion", paragraphIdx: v2InsSet[k].paraIdx,
        paraId: ins.paraId, text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.retained++; return;
    }
    if (inV2Clean(ins.text)) {
      transitions.push({
        type: "accepted-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
        text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.accepted++;
    } else {
      transitions.push({
        type: "rejected-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
        text: ins.text, author: ins.author, date: ins.date, source: "v1",
      });
      counts.rejected++;
    }
  });
  // v1 deletions: retained-pending / rejected / accepted
  Object.keys(v1DelSet).forEach(function (k) {
    var del = v1DelSet[k];
    if (v2DelSet[k]) {
      transitions.push({
        type: "retained-pending-deletion", paragraphIdx: v2DelSet[k].paraIdx,
        paraId: del.paraId, text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.retained++; return;
    }
    if (inV2Clean(del.text)) {
      transitions.push({
        type: "rejected-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
        text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.rejected++;
    } else {
      transitions.push({
        type: "accepted-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
        text: del.text, author: del.author, date: del.date, source: "v1",
      });
      counts.accepted++;
    }
  });
  // v2-only insertions/deletions: newly introduced
  Object.keys(v2InsSet).forEach(function (k) {
    if (v1InsSet[k]) return;
    var ins = v2InsSet[k];
    transitions.push({
      type: "new-insertion", paragraphIdx: ins.paraIdx, paraId: ins.paraId,
      text: ins.text, author: ins.author, date: ins.date, source: "v2",
    });
    counts.newRedlines++;
  });
  Object.keys(v2DelSet).forEach(function (k) {
    if (v1DelSet[k]) return;
    var del = v2DelSet[k];
    transitions.push({
      type: "new-deletion", paragraphIdx: del.paraIdx, paraId: del.paraId,
      text: del.text, author: del.author, date: del.date, source: "v2",
    });
    counts.newRedlines++;
  });
  // Whole-paragraph deletions (no redlines on a paragraph that vanished)
  var v2ParaIds = {};
  v2Paras.forEach(function (p) { if (p.paraId) v2ParaIds[p.paraId] = true; });
  v1Paras.forEach(function (p, v1i) {
    if (p.pendingIns.length || p.pendingDel.length) return;
    var clean = (p.acceptedText || "").trim();
    if (clean.length < 8) return;
    var paragraphSurvived = false;
    if (p.paraId && v2ParaIds[p.paraId]) paragraphSurvived = true;
    else if (inV2Clean(clean)) paragraphSurvived = true;
    if (!paragraphSurvived) {
      transitions.push({
        type: "accepted-deletion", paragraphIdx: v1i, paraId: p.paraId,
        text: clean, author: "", date: "", source: "v1",
      });
      counts.accepted++;
    }
  });
  // Unmarked-change detection (counterparty edits without track changes)
  var v1ById = {};
  v1Paras.forEach(function (p) { if (p.paraId) v1ById[p.paraId] = p; });
  var wordDiff = function (aText, bText) {
    var a = String(aText || "").split(/\s+/).filter(Boolean);
    var b = String(bText || "").split(/\s+/).filter(Boolean);
    var m = a.length, n = b.length;
    if (m === 0 && n === 0) return { inserted: [], deleted: [] };
    var dp = new Array(m + 1);
    for (var i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1);
    for (var i2 = 1; i2 <= m; i2++) {
      for (var j = 1; j <= n; j++) {
        if (a[i2 - 1].toLowerCase() === b[j - 1].toLowerCase()) dp[i2][j] = dp[i2 - 1][j - 1] + 1;
        else dp[i2][j] = dp[i2 - 1][j] >= dp[i2][j - 1] ? dp[i2 - 1][j] : dp[i2][j - 1];
      }
    }
    var inserted = [], deleted = [];
    var ii = m, jj = n;
    while (ii > 0 && jj > 0) {
      if (a[ii - 1].toLowerCase() === b[jj - 1].toLowerCase()) { ii--; jj--; }
      else if (dp[ii - 1][jj] >= dp[ii][jj - 1]) { deleted.unshift(a[ii - 1]); ii--; }
      else { inserted.unshift(b[jj - 1]); jj--; }
    }
    while (ii > 0) { deleted.unshift(a[ii - 1]); ii--; }
    while (jj > 0) { inserted.unshift(b[jj - 1]); jj--; }
    return { inserted: inserted, deleted: deleted };
  };
  var multisetIntersect = function (xs, ys) {
    var bag = {};
    xs.forEach(function (w) { var k = w.toLowerCase(); bag[k] = (bag[k] || 0) + 1; });
    var out = [];
    ys.forEach(function (w) { var k = w.toLowerCase(); if (bag[k] > 0) { out.push(w); bag[k]--; } });
    return out;
  };
  // Inline unmarked changes
  v2Paras.forEach(function (v2p, v2i) {
    if (!v2p.paraId) return;
    var v1p = v1ById[v2p.paraId];
    if (!v1p) return;
    var v1A = v1p.acceptedText || "", v2A = v2p.acceptedText || "";
    var v1Ro = v1p.originalText || "", v2Ro = v2p.originalText || "";
    if (normText(v1A) === normText(v2A) && normText(v1Ro) === normText(v2Ro)) return;
    var accDiff = wordDiff(v1A, v2A);
    var rejDiff = wordDiff(v1Ro, v2Ro);
    var unmarkedIns = multisetIntersect(accDiff.inserted, rejDiff.inserted);
    var unmarkedDel = multisetIntersect(accDiff.deleted, rejDiff.deleted);
    if (unmarkedIns.length === 0 && unmarkedDel.length === 0) return;
    var insStr = unmarkedIns.join(" ").replace(/[^\w]/g, "");
    var delStr = unmarkedDel.join(" ").replace(/[^\w]/g, "");
    if (insStr.length + delStr.length < 3) return;
    transitions.push({
      type: "unmarked-change", paragraphIdx: v2i, paraId: v2p.paraId,
      text: (unmarkedIns.length ? "+\"" + unmarkedIns.join(" ") + "\"" : "") +
            (unmarkedIns.length && unmarkedDel.length ? "  " : "") +
            (unmarkedDel.length ? "−\"" + unmarkedDel.join(" ") + "\"" : ""),
      addedText: unmarkedIns.join(" "), removedText: unmarkedDel.join(" "),
      author: "(no track changes)", date: "", source: "v2",
    });
    counts.unmarked++;
  });
  // Whole-paragraph unmarked additions
  v2Paras.forEach(function (v2p, v2i) {
    if (!v2p.paraId) return;
    if (v1ById[v2p.paraId]) return;
    if (v2p.pendingIns.length || v2p.pendingDel.length) return;
    var clean = (v2p.acceptedText || "").trim();
    if (clean.length < 8) return;
    if (inV1Clean(clean)) return;
    transitions.push({
      type: "unmarked-change", paragraphIdx: v2i, paraId: v2p.paraId,
      text: "+\"" + (clean.length > 240 ? clean.slice(0, 240) + "…" : clean) + "\"  (entire paragraph added without track changes)",
      addedText: clean, removedText: "",
      author: "(no track changes)", date: "", source: "v2", wholeParagraph: true,
    });
    counts.unmarked++;
  });
  // Group fragmented Word redlines (single user edit split across multiple <w:ins>)
  var grouped = {};
  var orderedKeys = [];
  transitions.forEach(function (t) {
    var key = t.paragraphIdx + "|" + t.type + "|" + (t.author || "") + "|" + (t.date || "").slice(0, 10);
    if (!grouped[key]) { grouped[key] = Object.assign({}, t); orderedKeys.push(key); }
    else {
      var prev = grouped[key].text || "";
      var add = t.text || "";
      if (prev.toLowerCase().indexOf(add.toLowerCase()) === -1) {
        grouped[key].text = prev ? prev + " " + add : add;
      }
    }
  });
  var mergedTransitions = orderedKeys.map(function (k) { return grouped[k]; });
  var mergedCounts = { accepted: 0, rejected: 0, newRedlines: 0, retained: 0, unmarked: 0 };
  mergedTransitions.forEach(function (t) {
    if (t.type === "accepted-insertion" || t.type === "accepted-deletion") mergedCounts.accepted++;
    else if (t.type === "rejected-insertion" || t.type === "rejected-deletion") mergedCounts.rejected++;
    else if (t.type === "new-insertion" || t.type === "new-deletion") mergedCounts.newRedlines++;
    else if (t.type.indexOf("retained-") === 0) mergedCounts.retained++;
    else if (t.type === "unmarked-change") mergedCounts.unmarked++;
  });
  return { transitions: mergedTransitions, summary: mergedCounts };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // v2-style smile loader DOM. Closure-scoped so the bundler treats
  // init() as the only top-level function. CSS for .robot-head /
  // .teeth-row / .brush-anim ships with error_review's bundle.
  function _cmpPaintSmileLoader() {
    var loader = document.getElementById("loading");
    if (!loader || loader.querySelector(".robot-head")) return;
    loader.style.background = "transparent";
    loader.style.border = "none";
    loader.style.boxShadow = "none";
    loader.innerHTML =
      '<div class="loading-card robot-loader" style="background:transparent;border:none;box-shadow:none;padding:10px 0;">' +
        '<div class="robot-head">' +
          '<div class="robot-eyes"><div class="robot-eye"></div><div class="robot-eye"></div></div>' +
          '<div class="mouth-container">' +
            '<div class="teeth-row upper">' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div>' +
            '</div>' +
            '<div class="teeth-row lower">' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div>' +
            '</div>' +
            '<div class="brush-anim">🪥</div>' +
            '<div class="foam f1"></div><div class="foam f2"></div><div class="foam f3"></div>' +
          '</div>' +
        '</div>' +
        '<p class="loading-text" style="margin-top:15px;font-weight:700;color:#1565c0;font-size:13px;">Comparing documents…</p>' +
      '</div>';
  }

  // ─── v2 PROMPTS / getPrompt / formatPrompt — tool-owned ───────────
  // Compare is the primary consumer of PROMPTS.COMPARE (own
  // runVersionCompare + delegates to risk_rules_manager's
  // runDeal360Analysis). Boot-tier load order means these window
  // globals are available before any caller fires.
  //
  // PROMPTS.COMPARE template is INLINED verbatim from v2 (working
  // pre-audit snapshot). The earlier IDB-routed version silently
  // failed when the prompts data bundle wasn't installed in the
  // user's IDB — the AI got called with an empty prompt and the
  // compare overlay never rendered. Self-contained + zero IDB
  // dependency = identical to how v2 worked.
  if (!window._cmpPromptsInstalled) {
    window._cmpPromptsInstalled = true;
    var _promptCache = null;
    var _promptCacheLoading = null;
    function _loadCache() {
      if (_promptCache) return Promise.resolve(_promptCache);
      if (_promptCacheLoading) return _promptCacheLoading;
      if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
      _promptCacheLoading = eli.storage.getAll("prompts").then(function (rows) {
        var map = {};
        (rows || []).forEach(function (r) {
          if (r && r.id && typeof r.text === "string") map[r.id] = r.text;
        });
        _promptCache = map;
        _promptCacheLoading = null;
        return map;
      }).catch(function () { _promptCacheLoading = null; return {}; });
      return _promptCacheLoading;
    }
    _loadCache();
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("data:installed", function (payload) {
        if (!payload || !payload.id || /prompts/i.test(payload.id)) _promptCache = null;
        _loadCache();
      });
    }
    if (typeof window.getPrompt !== "function") {
      window.getPrompt = function (key, fallback) {
        if (!_promptCache && !_promptCacheLoading) _loadCache();
        return (_promptCache || {})[key] || fallback || "";
      };
    }
    if (typeof window.formatPrompt !== "function") {
      window.formatPrompt = function (key, params, fallback) {
        var tpl = window.getPrompt(key, fallback);
        if (!tpl) return "";
        params = params || {};
        return tpl.replace(/\{\{(\w+)\}\}/g, function (_, name) {
          return params[name] != null ? String(params[name]) : "";
        });
      };
    }
    if (typeof window.PROMPTS !== "object" || !window.PROMPTS) window.PROMPTS = {};
    if (typeof window.PROMPTS.COMPARE !== "function") {
      window.PROMPTS.COMPARE = function (docA, docB, mode, poMode) {
        var labelA = mode === "template" ? "STANDARD TEMPLATE" : "OLD VERSION";
        var labelB = mode === "template" ? "DRAFT" : "NEW VERSION";
        var originInstructions;
        if (poMode === "3rd party") {
          originInstructions = "\n    >>> THIRD-PARTY PAPER MODE <<<\n    THIS DRAFT WAS NOT BASED ON OUR TEMPLATE. Do NOT do a literal word-for-word comparison because the boilerplate structures will inherently differ.\n    Instead, act as a semantic conceptual mapper by following these steps:\n    1. EXTRACT & MAP: First, mentally extract the core legal concepts from both documents. Map them conceptually (e.g. Draft Indemnity vs Template Indemnity) REGARDLESS of where they physically appear or how they are numbered in the text.\n    2. MICRO-COMPARE: Only compare the conceptually paired clauses. IGNORE stylings, structural ordering (e.g. moving a clause from Section 2 to 14), and boilerplate introductory wording.\n    3. ONLY REPORT MATERIAL DEVIATIONS IN LEGAL POSITION (e.g., Liability Caps, varying Cure Periods, missing Mutualities, different Warranty standards).\n    4. If the draft accomplishes the exact same legal intent as the template but uses different phrasing or is located in a different section, DO NOT REPORT THIS AS A CHANGE.\n    5. CRITICAL: If a material concept, protection, or right exists in the STANDARD TEMPLATE but fails to map to any semantic equivalent in the DRAFT, you MUST report it! Set 'new_snippet' to '[DELETED]'.\n    6. RECALL BIAS: When uncertain between \"same intent\" vs \"different legal effect\", prefer reporting as a change (Moderate unless clearly Critical/Minor) rather than suppressing.\n    7. COVERAGE CHECKLIST: Explicitly verify and report variance/missing coverage for: payment timing and milestones, liability cap amount/scope, indemnity scope and carve-outs, IP ownership/license terms, confidentiality term/survival, audit rights, data privacy/security obligations, termination triggers/cure windows, governing law/forum, assignment/subcontracting, warranties/disclaimers, insurance, and limitation carve-outs.\n    8. VOCABULARY: Do NOT use redlining terminology like \"Removal of\", \"Changed from\", or \"Modified\". This is a completely different document. Use auditing terminology: \"Draft omits...\", \"Draft deviates from standard by...\", or \"Draft takes alternate position on...\".";
        } else {
          originInstructions = "\n    >>> OUR PAPER MODE (STRICT REDLINE) <<<\n    This draft is based directly on the " + labelA + ". Run a strict, literal text diff with high recall.\n    Identify all removed phrases, altered limits, modified wording, qualifier changes (e.g., \"reasonable\", \"material\"), numeric/date changes, and scope narrowing/broadening.";
        }
        var returnFormat;
        if (poMode === "3rd party") {
          returnFormat = "\n    CRITICAL SCORING INSTRUCTION:\n    You must evaluate the holistic legal alignment of the Draft against the Standard Template and output a \"similarity_score\" (Integer 0-100). \n    DO NOT base this score purely on word-count or text overlap. You must weight the score based on LEGAL LEVERAGE and RISK POSTURE.\n    If the draft materially alters, guts, or omits critical risk-shifting clauses—specifically Intellectual Property Ownership, Limitation of Liability, Indemnification, or Termination rights—you MUST drastically lower the score (e.g., 20-50%), even if 90% of the standard boilerplate text remains unchanged. A highly restrictive or one-sided draft must never score above 60%.\n\n    RETURN RAW JSON OBJECT:\n    {\n       \"similarity_score\": 40,\n       \"similarity_text\": \"One sentence explaining the score.\",\n       \"critical_summary\": [\"Draft omits standard limitation of liability cap.\"],\n       \"overall_assessment\": \"One sentence summarizing the overall posture of this draft.\",\n       \"changes\": [{\"section\": \"Clause Name\", \"change_type\": \"Critical|Moderate|Minor\", \"description\": \"...\", \"legal_impact\": \"...\", \"id\": \"e.g. '_ELI_LR_5' or ''\", \"original_snippet\": \"verbatim or '[NEWLY ADDED]'\", \"new_snippet\": \"verbatim or '[DELETED]'\"}]\n    }";
        } else {
          returnFormat = "RETURN RAW JSON OBJECT:\n    {\n       \"critical_summary\": [\"Counterparty deleted the 30-day cure period.\"],\n       \"overall_assessment\": \"One sentence summary.\",\n       \"changes\": [{\"section\": \"Clause Name\", \"change_type\": \"Critical|Moderate|Minor\", \"description\": \"...\", \"legal_impact\": \"...\", \"id\": \"e.g. '_ELI_LR_5' or ''\", \"original_snippet\": \"verbatim or '[NEWLY ADDED]'\", \"new_snippet\": \"verbatim or '[DELETED]'\"}]\n    }";
        }
        return "You are a Senior Legal Editor for Colgate-Palmolive and where relevant its subsidiary Hill's Pet Nutrition.\n    TASK: Compare \"" + labelA + "\" against \"" + labelB + "\" and report changes.\n    " + originInstructions + "\n    STRICT REPORTING RULES:\n    1. NO HALLUCINATIONS: Only report a change if you can find the exact text in the source.\n    2. HEADING PROTECTION: Do NOT report Section Headings as Added if only the body changed.\n    3. STATE LABELS: missing → new_snippet=[DELETED]; addition → original_snippet=[NEWLY ADDED]; modification → full verbatim text.\n    4. VERBATIM SNIPPETS ONLY: snippet fields must be exact substrings.\n    5. COMPREHENSIVE EXTRACTION: be exhaustive across all substantive legal provisions.\n    6. GROUPING: one delta per changes entry.\n    7. IGNORE renumbering / whitespace / fonts.\n    " + returnFormat + "\n    --- " + labelA + " ---\n    " + String(docA || "").substring(0, 1000000) + "\n    --- " + labelB + " ---\n    " + String(docB || "").substring(0, 1000000);
      };
    }
  }

  // The compare tool's functions are top-level in their v2 files — the
  // bundler exposes them via window.* on eval. Capture refs once so we
  // can wire them through eli.register without re-checking each call.
  var showCompareToTemplateApp = window.showCompareToTemplateApp;
  var runVersionCompare        = window.runVersionCompare;
  var showTemplateSelectionOverlay = window.showTemplateSelectionOverlay;
  if (!showCompareToTemplateApp) {
    eli.log.event("tool", "compare_load_failed", { fns: Object.keys(window).filter(function (k) { return /^show|^run|^compare/i.test(k); }) });
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  // Click the Compare tile → launch the picker (template / upload /
  // past version). Records stat for usage tracking + leaves an activity
  // entry so the user can restore later.
  function _launch() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedCompare"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); }
    catch (e) {}
    try { showCompareToTemplateApp(); }
    catch (e) {
      eli.log.event("tool", "compare_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Compare failed to open: " + (e.message || "unknown"), "err");
    }
  }

  // Called by legal_risks after its risk scan when the launcher set a
  // comparePayload. Builds the baseline doc text, fires PROMPTS.COMPARE,
  // and renders the missing/deviations/additions buckets into the
  // _eli3_lr_compare_target div placed at the top of the risks view.
  function _runFromLauncher(opts) {
    if (!opts || !opts.payload) return Promise.resolve();
    var payload = opts.payload;
    var mode = opts.mode || "new";
    var targetId = opts.targetId || "_eli3_lr_compare_target";

    var baseline = "";
    if (payload.template) {
      baseline = payload.template.content || "";
    } else if (payload.version) {
      if (payload.version.html) {
        baseline = String(payload.version.html).replace(/<[^>]+>/g, " ");
      } else {
        baseline = payload.version.text || "";
      }
    } else if (payload.text) {
      baseline = payload.text;
    }
    if (!baseline) return Promise.resolve();

    // poMode = "3rd party" when comparing against a saved template OR
    // an uploaded doc (we're the standard, they're the deviation). For
    // a past version, both sides came from us — strict-redline mode.
    var poMode = (mode === "template" || mode === "new") ? "3rd party" : "our";

    return eli.host.readText({}).then(function (currentText) {
      var prompt = window.PROMPTS.COMPARE(baseline, currentText, mode, poMode);
      return eli.ai.completeJSON(prompt);
    }).then(function (data) {
      if (typeof window.renderCompareResults === "function") {
        window.renderCompareResults(data, mode, targetId);
      }
    }).catch(function (err) {
      eli.log.event("tool", "compare_run_failed", { msg: err && err.message });
    });
  }

  eli.register({
    tile: { app_compare: _launch },
    // Programmatic launch path for cross-tool callers (e.g. legal_review
    // dispatches into compare when a third-party doc matches a template).
    compare: {
      launch: _launch,
      versionCompare: function (historicalVersion) {
        if (typeof runVersionCompare === "function") {
          try { runVersionCompare(historicalVersion); }
          catch (e) {
            eli.log.event("tool", "compare_version_failed", { msg: e && e.message });
          }
        }
      },
      // Called by legal_risks after its scan when a comparePayload was set.
      run: _runFromLauncher,
    },
    // Activity-feed restoration — when the user clicks an old compare
    // entry in the feed, re-open the picker so they can re-run.
    activity_restore: {
      "compare": function () { _launch(); },
      "compare-template": function () { _launch(); },
    },
  });

  // ─── Helpers exposed for the v2 files ────────────────────────────
  // Compare's existing files reference these utilities expected to be
  // global. v3 kernel provides showHome, showToast, callGemini, etc.
  // — only the data-store loader needs a v3 bridge here so the rest of
  // the v2 code can stay untouched.
  //
  // loadFeatureData shim removed 2026-05-12 — call sites use
  // `window.eli.storage.getAll(store).then(filter underscored)` inline.

  // saveFeatureData shim removed 2026-05-12 — call sites use
  // `window.eli.storage.put(store, row)` directly.

  // ─── Additional v2 globals compare still reaches for ─────────────
  // Identified by the 2026-05-12 compare-port audit. Each was a
  // silent gap (the calls succeeded but with degraded behavior or no
  // effect). Bridge here once instead of patching every call site.

  // recordEliStat shim removed 2026-05-12 — call sites use
  // `window.eli.stats.record(name, count)` directly.

  // `addActivity` + `tryParseGeminiJSON` shims removed 2026-05-12:
  // risk_rules_manager calls `window.eli.activity.add` directly;
  // compare + final_review + risk_rules_manager each own a small
  // JSON-recovery helper in their own bundles.

  // v2 `jumpToBookmark(textOrAnchor)` — compareLocateFromCard tries
  // this first when navigating to a clause. v3 equivalent is
  // eli.host.highlightAnchor (when arg is an anchor name) OR a body
  // search + select (when arg is plaintext). Bridge both shapes.
  if (typeof window.jumpToBookmark !== "function") {
    window.jumpToBookmark = function (textOrAnchor) {
      if (!textOrAnchor || !eli.host) return;
      var s = String(textOrAnchor);
      // Looks like a bookmark name (no spaces, letter-leading).
      if (/^[A-Za-z][A-Za-z0-9_]*$/.test(s) && typeof eli.host.highlightAnchor === "function") {
        return eli.host.highlightAnchor(s).catch(function () {
          if (typeof showToast === "function") showToast("Bookmark not found: " + s, "warn");
        });
      }
      // Plain text — search + select.
      if (typeof eli.host.runRaw !== "function") return;
      return eli.host.runRaw("compare:jump_to_text", function (context) {
        var results = context.document.body.search(s.substring(0, 250), {
          matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
        });
        results.load("items");
        return context.sync().then(function () {
          if (!results.items.length) return false;
          try { results.items[0].select(); } catch (e) {}
          try { results.items[0].scrollIntoView(); } catch (e) {}
          return context.sync().then(function () { return true; });
        });
      }).then(function (found) {
        if (!found && typeof showToast === "function") {
          showToast("Not found in document", "warn");
        }
      });
    };
  }

  // v2 `getAgreementTypeMatcher()` — compare's _matchesAgreementType
  // falls back to empty catalog when this is missing, which degrades
  // alias matching (MSA → "Master Services Agreement", etc.). Pull
  // the same data from STORE_AGREEMENT_TYPES that v3 tools use.
  if (typeof window.getAgreementTypeMatcher !== "function") {
    window.getAgreementTypeMatcher = function () {
      // Synchronous return — best-effort. If the data hasn't loaded
      // yet, returns []; caller already handles that case.
      var cached = window._eliAgreementTypesCache;
      if (cached) return cached;
      // Kick off an async load so the next call has data.
      if (eli.storage && typeof eli.storage.getAll === "function") {
        eli.storage.getAll("agreement_types").then(function (rows) {
          window._eliAgreementTypesCache = (rows || []).filter(function (r) {
            return r && r.label && (!r.id || String(r.id).charAt(0) !== "_");
          });
        }).catch(function () {});
      }
      return [];
    };
  }

  // v2 `_tpStripOoxmlNoise(xml)` — strips rsid/date noise from OOXML
  // so OOXML diff isn't drowned in formatting artifacts. Compare's
  // runVersionCompare calls this when it has both snapshots. Provide
  // a minimal version (strip rsid attributes only).
  if (typeof window._tpStripOoxmlNoise !== "function") {
    window._tpStripOoxmlNoise = function (xml) {
      if (!xml || typeof xml !== "string") return xml || "";
      return xml
        .replace(/\s+w:rsid[A-Za-z]*="[^"]*"/g, "")
        .replace(/\s+w:rsidRoot="[^"]*"/g, "")
        .replace(/\s+w14:editId="[^"]*"/g, "");
    };
  }

  // Expose the ported snapshot-redline functions as globals so the v2
  // tools (runVersionCompare.js) find them under the same names they
  // used in v2. The functions themselves live in snapshotsRedlineAware.js
  // (loaded via tool_configs.files) and run pure over OOXML strings.
  if (typeof compareSnapshotsRedlineAware === "function" &&
      typeof window.compareSnapshotsRedlineAware !== "function") {
    window.compareSnapshotsRedlineAware = compareSnapshotsRedlineAware;
  }
  if (typeof _eliExtractParagraphRedlineSpans === "function" &&
      typeof window._eliExtractParagraphRedlineSpans !== "function") {
    window._eliExtractParagraphRedlineSpans = _eliExtractParagraphRedlineSpans;
  }

  // checkRedlinesBeforeScan shim removed 2026-05-12 — risk_rules_manager
  // now owns its own redline gate (_rrmRedlineGate) and reads via
  // eli.host.hasRedlines(). compare itself doesn't call it.

  // v2 `getLegalTextWithAnchors(prefix, loadingType)` — bookmarks every
  // paragraph with `<prefix>_<n>` then returns the doc as a JSON-
  // stringified array of `[{id, text}, ...]`. v3 has the underlying
  // call on the provider; we wrap to match v2's return shape.
  if (typeof window.getLegalTextWithAnchors !== "function") {
    window.getLegalTextWithAnchors = function (prefix, loadingType) {
      if (!eli.host || typeof eli.host.readTextWithAnchors !== "function") {
        return Promise.resolve("[]");
      }
      // v3 bookmark names MUST start with a letter (OOXML rule).
      // Strip a single leading underscore if v2 caller passed one
      // (legal_risks-era prefixes were "_ELI_LR_").
      var safePrefix = String(prefix || "ELI_").replace(/^_+/, "");
      if (loadingType && typeof window.setLoading === "function") {
        try { _cmpPaintSmileLoader(); } catch (_) {}
        try { window.setLoading(true, loadingType); } catch (e) {}
      }
      return eli.host.readTextWithAnchors({ prefix: safePrefix, minLen: 5 })
        .then(function (anchors) { return JSON.stringify(anchors || []); })
        .catch(function () { return "[]"; });
    };
  }

  // v2 `checkQuirkyTrophy(name, payload)` — re-routed to v3 trophies
  // channel. Tools that fire quirky-trophy events can keep using the
  // v2 name without knowing the kernel split.
  if (typeof window.checkQuirkyTrophy !== "function") {
    window.checkQuirkyTrophy = function (name, payload) {
      try {
        if (eli.dispatch) {
          eli.dispatch("trophies", "unlocked", {
            id: String(name || "quirky"),
            icon: "🏆",
            title: String(name || "Achievement"),
            desc: "",
            quirkyPayload: payload || null,
          });
        }
      } catch (e) { /* tolerate */ }
    };
  }

  // getPrompt / formatPrompt / PROMPTS now live in the kernel — single
  // source of truth (taskpane_v3.js, after the callGemini shim). Kept
  // here as a pointer so the next dev doesn't re-add a per-tool copy.

  // v2 `askUserSelectionScope()` — popped a dialog asking the user
  // whether to scan the SELECTION or the WHOLE document when they had
  // text selected. v3 version_history / risk_rules_manager call this.
  // Default to "fullDoc" so the scan runs without an extra interrupt.
  if (typeof window.askUserSelectionScope !== "function") {
    window.askUserSelectionScope = function () {
      // Tiny premium picker. Resolves "selection" or "fullDoc".
      if (typeof showEliDialog !== "function") return Promise.resolve("fullDoc");
      return new Promise(function (resolve, reject) {
        showEliDialog({
          variant: "info", icon: "📐",
          title: "Scan scope",
          body:
            '<div style="font:500 12px/1.5 \'Inter\',sans-serif;color:#475569;">' +
              'You have text selected. Scan just the selection or the whole document?' +
            '</div>',
          primary: { label: "Whole document", onclick: function () { resolve("fullDoc"); } },
          secondary: { label: "Just selection", onclick: function () { resolve("selection"); } },
          onClose: function () { reject(new Error("Cancelled")); },
        });
      });
    };
  }

  // v2 `handleFileSelect(file, cb)` — reads a .docx/.pdf file and calls
  // back with extracted text. compare uses this for the "upload file"
  // comparison source. Kernel doesn't expose this; for v3 we use the
  // ask_eli reader if loaded, else a minimal text-only fallback.
  if (typeof window.handleFileSelect !== "function") {
    window.handleFileSelect = function (file, cb) {
      var reader = new FileReader();
      reader.onload = function () {
        var content = reader.result;
        // .txt: decode bytes directly.
        if (typeof content === "string") return cb(content);
        // .docx/.pdf: needs mammoth/pdf.js. If not available, hand the
        // file off to the AI as a binary attachment (compare's downstream
        // legal_risks engine handles binary input via eli.ai.complete).
        try {
          var bytes = new Uint8Array(content);
          var sample = Array.prototype.slice.call(bytes.slice(0, 4))
            .map(function (b) { return String.fromCharCode(b); }).join("");
          // .docx starts with "PK" (zip header), .pdf with "%PDF".
          if (sample.indexOf("%PDF") === 0 && typeof window.pdfjsLib !== "undefined") {
            // pdf.js path (kernel may load it on demand).
            cb("[PDF text extraction requires pdf.js — paste the text manually]");
            return;
          }
          if (sample.indexOf("PK") === 0 && typeof window.mammoth !== "undefined") {
            window.mammoth.extractRawText({ arrayBuffer: content }).then(function (res) {
              cb(res && res.value ? res.value : "");
            }).catch(function () { cb(""); });
            return;
          }
          // No extractor available — best we can do is pass empty + warn.
          if (typeof showToast === "function") {
            showToast("File reader unavailable for " + (file.name || "this format"), "warn");
          }
          cb("");
        } catch (e) {
          cb("");
        }
      };
      reader.onerror = function () { cb(""); };
      // .docx + .pdf → arrayBuffer, .txt → text.
      var name = String(file.name || "").toLowerCase();
      if (name.endsWith(".txt")) reader.readAsText(file);
      else reader.readAsArrayBuffer(file);
    };
  }

  // ─── Activity entry on compare launch ────────────────────────────
  // Wrap _launch so each open writes an entry; restoration re-launches.
  // Done via bus rather than mutating _launch directly so future
  // observers (e.g. wrongness capture) can hook in cleanly.
  if (eli.bus && typeof eli.bus.emit === "function") {
    var origLaunch = _launch;
    _launch = function () {
      if (eli.activity && eli.activity.add) {
        try {
          eli.activity.add({
            type: "compare",
            icon: "📑",
            label: "Compare Draft",
            summary: "Opened Compare picker",
            payload: { ts: Date.now() },
            restoreChannel: "activity_restore",
            restoreKey: "compare",
          });
        } catch (e) {}
      }
      return origLaunch();
    };
  }

  eli.log.event("tool", "compare_initialized", {});
}
